// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Apple 登录
	// (POST /v1/auth/apple)
	LoginApple(ctx context.Context, request LoginAppleRequestObject) (LoginAppleResponseObject, error)
	// 退出登录（吊销该刷新令牌）
	// (POST /v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// 运营商一键登录（阿里云号码认证 token）
	// (POST /v1/auth/phone/oneclick)
	LoginPhoneOneClick(ctx context.Context, request LoginPhoneOneClickRequestObject) (LoginPhoneOneClickResponseObject, error)
	// 用刷新令牌换新令牌（刷新令牌轮换，旧的立即失效）
	// (POST /v1/auth/refresh)
	RefreshSession(ctx context.Context, request RefreshSessionRequestObject) (RefreshSessionResponseObject, error)
	// 发送短信验证码
	// (POST /v1/auth/sms/send)
	SendSmsCode(ctx context.Context, request SendSmsCodeRequestObject) (SendSmsCodeResponseObject, error)
	// 短信验证码登录（新用户自动注册）
	// (POST /v1/auth/sms/verify)
	VerifySmsCode(ctx context.Context, request VerifySmsCodeRequestObject) (VerifySmsCodeResponseObject, error)
	// 微信登录（OpenSDK 授权 code）
	// (POST /v1/auth/wechat)
	LoginWechat(ctx context.Context, request LoginWechatRequestObject) (LoginWechatResponseObject, error)
	// 我的定时简报
	// (GET /v1/briefing-subscriptions)
	ListSubscriptions(ctx context.Context, request ListSubscriptionsRequestObject) (ListSubscriptionsResponseObject, error)
	// 新建定时简报。超过套餐上限返回 403 quota_exceeded
	// (POST /v1/briefing-subscriptions)
	CreateSubscription(ctx context.Context, request CreateSubscriptionRequestObject) (CreateSubscriptionResponseObject, error)
	// 一句话解析成定时简报草稿（不落库）
	// (POST /v1/briefing-subscriptions/draft)
	DraftSubscription(ctx context.Context, request DraftSubscriptionRequestObject) (DraftSubscriptionResponseObject, error)

	// (DELETE /v1/briefing-subscriptions/{subscriptionId})
	DeleteSubscription(ctx context.Context, request DeleteSubscriptionRequestObject) (DeleteSubscriptionResponseObject, error)

	// (GET /v1/briefing-subscriptions/{subscriptionId})
	GetSubscription(ctx context.Context, request GetSubscriptionRequestObject) (GetSubscriptionResponseObject, error)

	// (PATCH /v1/briefing-subscriptions/{subscriptionId})
	UpdateSubscription(ctx context.Context, request UpdateSubscriptionRequestObject) (UpdateSubscriptionResponseObject, error)
	// 立即生成一期（预览）。返回任务，进度走 SSE，完成事件带 briefingId
	// (POST /v1/briefing-subscriptions/{subscriptionId}/run)
	RunSubscription(ctx context.Context, request RunSubscriptionRequestObject) (RunSubscriptionResponseObject, error)
	// 历史简报，新的在前
	// (GET /v1/briefings)
	ListBriefings(ctx context.Context, request ListBriefingsRequestObject) (ListBriefingsResponseObject, error)
	// 今日简报（用户时区的今天，每个订阅最多一期，含完整内容）
	// (GET /v1/briefings/today)
	ListTodayBriefings(ctx context.Context, request ListTodayBriefingsRequestObject) (ListTodayBriefingsResponseObject, error)

	// (GET /v1/briefings/{briefingId})
	GetBriefing(ctx context.Context, request GetBriefingRequestObject) (GetBriefingResponseObject, error)
	// 对整期或单条打分（同一对象重复提交以最后一次为准）
	// (PUT /v1/briefings/{briefingId}/feedback)
	PutBriefingFeedback(ctx context.Context, request PutBriefingFeedbackRequestObject) (PutBriefingFeedbackResponseObject, error)
	// 内置工具 + 白名单 MCP 连接器，及我的开关和授权状态
	// (GET /v1/connectors)
	ListConnectors(ctx context.Context, request ListConnectorsRequestObject) (ListConnectorsResponseObject, error)
	// 开关连接器。需要授权而未授权时开启返回 409 auth_required
	// (PATCH /v1/connectors/{connectorId})
	UpdateConnector(ctx context.Context, request UpdateConnectorRequestObject) (UpdateConnectorResponseObject, error)
	// 解除授权并删除凭证
	// (DELETE /v1/connectors/{connectorId}/authorization)
	RevokeConnector(ctx context.Context, request RevokeConnectorRequestObject) (RevokeConnectorResponseObject, error)
	// 开始授权。App 用 ASWebAuthenticationSession 打开 authUrl，完成后回调 zeus://oauth?connector={id}&status=ok|error
	// (POST /v1/connectors/{connectorId}/authorize)
	AuthorizeConnector(ctx context.Context, request AuthorizeConnectorRequestObject) (AuthorizeConnectorResponseObject, error)
	// 注册或更新推送设备（APNs token），幂等
	// (POST /v1/devices)
	RegisterDevice(ctx context.Context, request RegisterDeviceRequestObject) (RegisterDeviceResponseObject, error)

	// (DELETE /v1/devices/{pushToken})
	UnregisterDevice(ctx context.Context, request UnregisterDeviceRequestObject) (UnregisterDeviceResponseObject, error)
	// 注销账号（硬删除全部数据，不可恢复）
	// (DELETE /v1/me)
	DeleteAccount(ctx context.Context, request DeleteAccountRequestObject) (DeleteAccountResponseObject, error)
	// 当前用户、套餐与额度
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)

	// (PATCH /v1/me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// 清空全部记忆（硬删除，向量一起删）
	// (DELETE /v1/memories)
	DeleteAllMemories(ctx context.Context, request DeleteAllMemoriesRequestObject) (DeleteAllMemoriesResponseObject, error)

	// (GET /v1/memories)
	ListMemories(ctx context.Context, request ListMemoriesRequestObject) (ListMemoriesResponseObject, error)

	// (DELETE /v1/memories/{memoryId})
	DeleteMemory(ctx context.Context, request DeleteMemoryRequestObject) (DeleteMemoryResponseObject, error)

	// (GET /v1/reports)
	ListReports(ctx context.Context, request ListReportsRequestObject) (ListReportsResponseObject, error)

	// (DELETE /v1/reports/{reportId})
	DeleteReport(ctx context.Context, request DeleteReportRequestObject) (DeleteReportResponseObject, error)

	// (GET /v1/reports/{reportId})
	GetReport(ctx context.Context, request GetReportRequestObject) (GetReportResponseObject, error)
	// 针对报告追问。返回任务，答案以 text_delta 事件流式返回，并追加到报告末尾
	// (POST /v1/reports/{reportId}/followups)
	CreateReportFollowup(ctx context.Context, request CreateReportFollowupRequestObject) (CreateReportFollowupResponseObject, error)
	// 报告正文 HTML（App 用 WKWebView 带 Bearer 加载；与 H5 分享页同一模板）
	// (GET /v1/reports/{reportId}/html)
	GetReportHtml(ctx context.Context, request GetReportHtmlRequestObject) (GetReportHtmlResponseObject, error)
	// PDF 下载地址（短时签名链接）。尚未生成时返回 status=generating，稍后重试
	// (GET /v1/reports/{reportId}/pdf)
	GetReportPdf(ctx context.Context, request GetReportPdfRequestObject) (GetReportPdfResponseObject, error)
	// 生成 H5 分享链接
	// (POST /v1/reports/{reportId}/shares)
	CreateShare(ctx context.Context, request CreateShareRequestObject) (CreateShareResponseObject, error)
	// 撤销分享，链接立即失效
	// (DELETE /v1/shares/{shareId})
	RevokeShare(ctx context.Context, request RevokeShareRequestObject) (RevokeShareResponseObject, error)

	// (GET /v1/tasks)
	ListTasks(ctx context.Context, request ListTasksRequestObject) (ListTasksResponseObject, error)
	// 发起调研报告。超出本月额度返回 403 quota_exceeded
	// (POST /v1/tasks)
	CreateTask(ctx context.Context, request CreateTaskRequestObject) (CreateTaskResponseObject, error)

	// (GET /v1/tasks/{taskId})
	GetTask(ctx context.Context, request GetTaskRequestObject) (GetTaskResponseObject, error)
	// 中止任务（已产出内容会尽量收尾保存）
	// (POST /v1/tasks/{taskId}/cancel)
	CancelTask(ctx context.Context, request CancelTaskRequestObject) (CancelTaskResponseObject, error)
	// 确认或拒绝一次写操作
	// (POST /v1/tasks/{taskId}/confirmations/{confirmId})
	ResolveConfirmation(ctx context.Context, request ResolveConfirmationRequestObject) (ResolveConfirmationResponseObject, error)
	// 任务事件流（SSE）
	// (GET /v1/tasks/{taskId}/events)
	StreamTaskEvents(ctx context.Context, request StreamTaskEventsRequestObject) (StreamTaskEventsResponseObject, error)
	// 运行中补充要求，Agent 在下一步读取
	// (POST /v1/tasks/{taskId}/messages)
	SendTaskMessage(ctx context.Context, request SendTaskMessageRequestObject) (SendTaskMessageResponseObject, error)
	// 模板列表（官方模板库 / 我的模板）
	// (GET /v1/templates)
	ListTemplates(ctx context.Context, request ListTemplatesRequestObject) (ListTemplatesResponseObject, error)
	// 新建自定义模板（仅自己可见）
	// (POST /v1/templates)
	CreateTemplate(ctx context.Context, request CreateTemplateRequestObject) (CreateTemplateResponseObject, error)
	// 一句话生成模板草稿（不落库，用户确认后再 createTemplate）
	// (POST /v1/templates/draft)
	DraftTemplate(ctx context.Context, request DraftTemplateRequestObject) (DraftTemplateResponseObject, error)

	// (DELETE /v1/templates/{templateId})
	DeleteTemplate(ctx context.Context, request DeleteTemplateRequestObject) (DeleteTemplateResponseObject, error)

	// (GET /v1/templates/{templateId})
	GetTemplate(ctx context.Context, request GetTemplateRequestObject) (GetTemplateResponseObject, error)
	// 修改自定义模板（官方模板不可改，可先复制）
	// (PATCH /v1/templates/{templateId})
	UpdateTemplate(ctx context.Context, request UpdateTemplateRequestObject) (UpdateTemplateResponseObject, error)
	// 复制模板为我的模板
	// (POST /v1/templates/{templateId}/copy)
	CopyTemplate(ctx context.Context, request CopyTemplateRequestObject) (CopyTemplateResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

